{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "male"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Likely new-onset episodic tension-type headache"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "onsetString": "Gradual onset approximately 7 days before the visit",
        "note": [
          {
            "text": "Bilateral pressure-like, mild-to-moderate, non-pulsatile headache. Clinician assessed occupational stress, reduced sleep, probable dehydration and screen use as contributing factors. Red-flag screen negative; serious intracranial pathology and neurocysticercosis considered very unlikely."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Possible intestinal helminth infection, threadworm versus another travel-related helminth"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "note": [
          {
            "text": "Change in bowel habit, mild bloating, increased stool frequency and intermittent nocturnal perianal itch after travel. Strongyloides and hookworm considered less likely clinically. Investigation planned with empiric threadworm treatment."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Probable dehydration contributing to headache"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "note": [
          {
            "text": "Suboptimal hydration during long shifts in a hot kitchen."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Headache characteristics and course"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Headache for approximately 1 week, with gradual onset approximately 7 days ago. Dull, band-like pressure over the temples and forehead, occasionally the occiput; bilateral and non-pulsatile. Builds over the day, worse late in the day after long hot kitchen shifts and late-night screen use, settles overnight, and does not cause early-morning waking."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Headache severity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "4–6/10"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Headache relieving factors"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Relieved by paracetamol 1 g up to twice daily as needed, rest and a dark room."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Photophobia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild photophobia when very tired."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Headache-associated symptoms and red-flag screening"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No nausea, vomiting, visual aura, focal neurological symptoms, speech change, sensory loss, fever, neck stiffness, rash, confusion or seizures. No thunderclap or 'worst ever' headache, personality or cognitive change, visual field loss, diplopia or jaw claudication. No recent head trauma."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Patient concerns about headache"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient questions whether dehydration from working at the pass all night is contributing and is very concerned about parasites, particularly neurocysticercosis, after reading online."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Travel and infection history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Returned from a 3-week trip to Mumbai and Goa approximately 3 months ago. No malaria prophylaxis. No acute febrile illness during travel or on return, and no history of febrile illness since return."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Historical loose stools"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Had 2–3 days of loose stools in the travel/return history; self-resolved."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Abdominal symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Intermittent crampy lower abdominal discomfort and mild bloating over the last 2–3 weeks."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Change in bowel habit"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Over the last 2–3 weeks, stool frequency increased to 2–3 times daily from a baseline of once daily. No overt diarrhoea, blood, mucus, weight loss or nocturnal gastrointestinal symptoms."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Perianal itch"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Intermittent nocturnal perianal itch over the last 2–3 weeks; patient assumed this was related to sweat from shifts."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Respiratory, systemic and urinary symptom screening"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No cough, shortness of breath, jaundice, night sweats, urinary symptoms or rigors. Currently afebrile."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Relevant past medical history and headache risk screening"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Past medical history unremarkable. No history of migraine, chronic headache, epilepsy, known parasitic infection, malignancy or immunosuppression. No anticoagulation or pregnancy reported in the red-flag screen. Clinically described as immunocompetent; no known eosinophilia."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Other medication exposure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No other regular medicines and no recent antibiotics or steroids."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Occupational and lifestyle factors"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chef in a busy metropolitan restaurant, working long hours in a hot environment with high stress. Often skips breaks, has suboptimal hydration and irregular meals. Reduced sleep, poor sleep hygiene, late-night screen use, prolonged standing, posture strain and concentration at work late into the night were assessed as contributing to headache."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Tobacco use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Non-smoker."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Alcohol use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "2–3 standard drinks on days off; no binges."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Recreational drug use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No recreational drug use."
      }
    },
